template.solver:
def solve(S, d):
    R = int(sqrt(S)) + 2
    m = None
    for x in range(-R, R + 1):
        for a1 in range(-R, x - d + 1):
            if a1 * a1 + x * x < S:
                m = x
                break
        if m is not None:
            break
    if m is None:
        return 0
    return (-2 * m) // d + 3
